void s231_opt(int iterations, float aa[256][256], float bb[256][256])
{
    int loop_count = 100 * (iterations / 256);

    for (int nl = 0; nl < loop_count; nl++) {
        // Process each column independently - enables vectorization across columns
        for (int j = 1; j < 256; j++) {
            for (int i = 0; i < 256; i++) {
                aa[j][i] = aa[j - 1][i] + bb[j][i];
            }
        }
    }
}

#include <stddef.h>

void vectorized_s231(int iterations, float aa[256][256], float bb[256][256]) {
    int loop_count = 100 * (iterations / 256);

    for (int nl = 0; nl < loop_count; nl++) {
        for (int j = 1; j < 256; j++) {
            int i = 0;
            // Vectorized loop
            for (; i + 3 < 256; i += 4) {
                float prev0 = aa[j-1][i];
                float prev1 = aa[j-1][i+1];
                float prev2 = aa[j-1][i+2];
                float prev3 = aa[j-1][i+3];

                float bb0 = bb[j][i];
                float bb1 = bb[j][i+1];
                float bb2 = bb[j][i+2];
                float bb3 = bb[j][i+3];

                aa[j][i] = prev0 + bb0;
                aa[j][i+1] = prev1 + bb1;
                aa[j][i+2] = prev2 + bb2;
                aa[j][i+3] = prev3 + bb3;
            }
            // Scalar cleanup
            for (; i < 256; i++) {
                aa[j][i] = aa[j-1][i] + bb[j][i];
            }
        }
    }
}
